import type { WixDataAggregateOptions } from './types'

/**
 * Options builder for aggregate operations.
 *
 * Use this builder to configure aggregation behavior such as language, consistent reads,
 * and total counts.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataAggregateOptionsBuilder {
  /**
   * Sets whether to include draft items in aggregation results.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataAggregateOptionsBuilder
  /**
   * Sets the language used for the aggregation.
   */
  withLanguage(value: string): WixDataAggregateOptionsBuilder
  /**
   * Sets whether the aggregation uses consistent read mode.
   */
  withConsistentRead(value: boolean): WixDataAggregateOptionsBuilder
  /**
   * Sets whether to return the total result count with the aggregation response.
   */
  withReturnTotalCount(value: boolean): WixDataAggregateOptionsBuilder
  /**
   * Builds the aggregate options object.
   */
  build(): WixDataAggregateOptions
}

class WixDataAggregateOptionsBuilderImpl
  implements WixDataAggregateOptionsBuilder
{
  constructor(private readonly options: WixDataAggregateOptions = {}) {}

  withShowDrafts(value: boolean): WixDataAggregateOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withLanguage(value: string): WixDataAggregateOptionsBuilder {
    return this.copy({ language: value })
  }

  withConsistentRead(value: boolean): WixDataAggregateOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  withReturnTotalCount(value: boolean): WixDataAggregateOptionsBuilder {
    return this.copy({ returnTotalCount: value })
  }

  build(): WixDataAggregateOptions {
    return { ...this.options }
  }

  private copy(
    options: WixDataAggregateOptions
  ): WixDataAggregateOptionsBuilder {
    return new WixDataAggregateOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new aggregate options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create an aggregate options builder"
 * import { items, AggregateOptionsBuilder } from '@wix/data'
 *
 *
 * const options = AggregateOptionsBuilder()
 *   .withLanguage('en')
 *   .withConsistentRead(true)
 *   .withReturnTotalCount(true)
 *   .build()
 *
 * const result = await items.aggregate<MyItem>(
 *   'myCollection',
 *   {},
 *   options
 * )
 * ```
 */
export const AggregateOptionsBuilder: () => WixDataAggregateOptionsBuilder =
  () => new WixDataAggregateOptionsBuilderImpl()
